PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_version(version INTEGER PRIMARY KEY);
INSERT OR IGNORE INTO schema_version VALUES(1);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
INSERT OR IGNORE INTO settings VALUES('timezone','America/Tegucigalpa'),('exchange_rate',''),('paper','letter');
CREATE TABLE IF NOT EXISTS entities(id INTEGER PRIMARY KEY,name TEXT NOT NULL,currency TEXT NOT NULL CHECK(currency IN ('HNL','USD')),status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','archived')),logo TEXT);
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT NOT NULL UNIQUE COLLATE NOCASE,full_name TEXT NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('superuser','operator')),active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)),must_change INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,last_login TEXT,failures INTEGER NOT NULL DEFAULT 0,locked_until TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS single_superuser ON users(role) WHERE role='superuser';
CREATE TRIGGER IF NOT EXISTS preserve_superuser BEFORE UPDATE OF active,role ON users WHEN OLD.role='superuser' AND (NEW.active<>1 OR NEW.role<>'superuser') BEGIN SELECT RAISE(ABORT,'Superusuario protegido'); END;
CREATE TABLE IF NOT EXISTS user_entities(user_id INTEGER REFERENCES users(id),entity_id INTEGER REFERENCES entities(id),PRIMARY KEY(user_id,entity_id));
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),csrf TEXT NOT NULL,last_seen TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS clients(id INTEGER PRIMARY KEY,entity_id INTEGER NOT NULL REFERENCES entities(id),name TEXT NOT NULL,document_type TEXT NOT NULL,document TEXT NOT NULL,phone TEXT NOT NULL,email TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '',created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,UNIQUE(entity_id,document_type,document),UNIQUE(id,entity_id));
CREATE TABLE IF NOT EXISTS lots(id INTEGER PRIMARY KEY,entity_id INTEGER NOT NULL REFERENCES entities(id),code TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',price INTEGER NOT NULL CHECK(price>0),currency TEXT NOT NULL CHECK(currency IN ('HNL','USD')),status TEXT NOT NULL DEFAULT 'available' CHECK(status IN ('available','reserved','sold')),UNIQUE(entity_id,code),UNIQUE(id,entity_id));
CREATE TABLE IF NOT EXISTS reservations(id INTEGER PRIMARY KEY,entity_id INTEGER NOT NULL REFERENCES entities(id),lot_id INTEGER NOT NULL,client_id INTEGER NOT NULL,expires_on TEXT NOT NULL,created_at TEXT NOT NULL,created_by INTEGER NOT NULL REFERENCES users(id),status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','released','converted')),FOREIGN KEY(lot_id,entity_id) REFERENCES lots(id,entity_id),FOREIGN KEY(client_id,entity_id) REFERENCES clients(id,entity_id));
CREATE UNIQUE INDEX IF NOT EXISTS one_reservation ON reservations(lot_id) WHERE status='active';
CREATE TABLE IF NOT EXISTS contracts(id INTEGER PRIMARY KEY,entity_id INTEGER NOT NULL REFERENCES entities(id),lot_id INTEGER NOT NULL,client_id INTEGER NOT NULL,price INTEGER NOT NULL CHECK(price>0),currency TEXT NOT NULL CHECK(currency IN ('HNL','USD')),down_payment INTEGER NOT NULL CHECK(down_payment>=0 AND down_payment<=price),installments INTEGER NOT NULL CHECK(installments>0),down_due TEXT NOT NULL,first_due TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',version INTEGER NOT NULL DEFAULT 1,created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,UNIQUE(id,entity_id),FOREIGN KEY(lot_id,entity_id) REFERENCES lots(id,entity_id),FOREIGN KEY(client_id,entity_id) REFERENCES clients(id,entity_id));
CREATE UNIQUE INDEX IF NOT EXISTS one_contract ON contracts(lot_id) WHERE status='active';
CREATE TABLE IF NOT EXISTS obligations(id INTEGER PRIMARY KEY,contract_id INTEGER NOT NULL REFERENCES contracts(id),number INTEGER NOT NULL,due_date TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>=0),paid INTEGER NOT NULL DEFAULT 0 CHECK(paid>=0 AND paid<=amount),UNIQUE(contract_id,number));
CREATE TABLE IF NOT EXISTS payments(id INTEGER PRIMARY KEY,entity_id INTEGER NOT NULL REFERENCES entities(id),contract_id INTEGER NOT NULL,client_id INTEGER NOT NULL,operation_id TEXT NOT NULL UNIQUE,request_hash TEXT NOT NULL,payment_date TEXT NOT NULL,received INTEGER NOT NULL CHECK(received>0),received_currency TEXT NOT NULL CHECK(received_currency IN ('HNL','USD')),applied INTEGER NOT NULL CHECK(applied>0),rate TEXT,method TEXT NOT NULL CHECK(method IN ('cash','deposit','transfer')),bank_reference TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '',created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'valid' CHECK(status IN ('valid','void')),balance_after INTEGER NOT NULL CHECK(balance_after>=0),void_by INTEGER REFERENCES users(id),void_reason TEXT,void_at TEXT,FOREIGN KEY(contract_id,entity_id) REFERENCES contracts(id,entity_id),FOREIGN KEY(client_id,entity_id) REFERENCES clients(id,entity_id));
CREATE TABLE IF NOT EXISTS allocations(payment_id INTEGER NOT NULL REFERENCES payments(id),obligation_id INTEGER NOT NULL REFERENCES obligations(id),amount INTEGER NOT NULL CHECK(amount>0),PRIMARY KEY(payment_id,obligation_id));
CREATE TABLE IF NOT EXISTS receipt_sequences(entity_id INTEGER REFERENCES entities(id),year INTEGER,number INTEGER NOT NULL,PRIMARY KEY(entity_id,year));
CREATE TABLE IF NOT EXISTS receipts(id INTEGER PRIMARY KEY,payment_id INTEGER NOT NULL UNIQUE REFERENCES payments(id),entity_id INTEGER NOT NULL REFERENCES entities(id),year INTEGER NOT NULL,number INTEGER NOT NULL,folio TEXT NOT NULL,snapshot TEXT NOT NULL,path TEXT,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','issued','void')),UNIQUE(entity_id,year,number));
CREATE TABLE IF NOT EXISTS transfers(id INTEGER PRIMARY KEY,contract_id INTEGER NOT NULL REFERENCES contracts(id),previous_client INTEGER NOT NULL REFERENCES clients(id),new_client INTEGER NOT NULL REFERENCES clients(id),effective_date TEXT NOT NULL,reason TEXT NOT NULL,balance INTEGER NOT NULL,created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS contract_versions(id INTEGER PRIMARY KEY,contract_id INTEGER NOT NULL REFERENCES contracts(id),version INTEGER NOT NULL,snapshot TEXT NOT NULL,reason TEXT NOT NULL,created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,UNIQUE(contract_id,version));
CREATE TABLE IF NOT EXISTS approvals(id INTEGER PRIMARY KEY,entity_id INTEGER NOT NULL REFERENCES entities(id),action TEXT NOT NULL CHECK(action IN ('void_payment','release_reservation','transfer_contract','amend_contract')),record_id INTEGER NOT NULL,payload TEXT NOT NULL,reason TEXT NOT NULL,requested_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),resolved_by INTEGER REFERENCES users(id),resolved_at TEXT,resolution TEXT);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,created_at TEXT NOT NULL,user_id INTEGER REFERENCES users(id),role TEXT,entity_id INTEGER REFERENCES entities(id),action TEXT NOT NULL,record_type TEXT,record_id INTEGER,result TEXT NOT NULL DEFAULT 'success',reason TEXT,before_json TEXT,after_json TEXT);
CREATE TRIGGER IF NOT EXISTS audit_no_update BEFORE UPDATE ON audit BEGIN SELECT RAISE(ABORT,'Auditoria inmutable'); END;
CREATE TRIGGER IF NOT EXISTS audit_no_delete BEFORE DELETE ON audit BEGIN SELECT RAISE(ABORT,'Auditoria inmutable'); END;
CREATE INDEX IF NOT EXISTS clients_entity ON clients(entity_id,name);
CREATE INDEX IF NOT EXISTS obligations_due ON obligations(due_date,contract_id);
CREATE INDEX IF NOT EXISTS payments_entity_date ON payments(entity_id,payment_date);
CREATE INDEX IF NOT EXISTS audit_user_date ON audit(user_id,created_at);
CREATE INDEX IF NOT EXISTS contracts_entity ON contracts(entity_id,client_id);
